package org.springframework.samples.petclinic.util;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * Helpers for the membership points and numeric level a pet owner is assigned. Points are derived
 * from the owner's own fields together with their tenure (time elapsed since registration), and the
 * level is a banding of those points.
 */
public final class Memberships {

    /**
     * The lowest membership level every owner starts from.
     */
    public static final int BASE_LEVEL = 1;

    /**
     * The highest membership level reachable. Level 4 is only reached with 6 or more points, and the
     * only route to 6 points is qualifying tenure (see {@link #TENURE_LEVEL_DAYS}) on top of the
     * other factors.
     */
    public static final int MAX_LEVEL = 4;

    /**
     * The points added when an email is present.
     */
    public static final int EMAIL_POINTS = 2;

    /**
     * The points added when {@code namesakeCount} is 0.
     */
    public static final int UNIQUE_NAME_POINTS = 1;

    /**
     * The points added for a household of {@link #HOUSEHOLD_POINTS_THRESHOLD} or more.
     */
    public static final int HOUSEHOLD_POINTS = 2;

    /**
     * The household size at or above which {@link #HOUSEHOLD_POINTS} are added.
     */
    public static final int HOUSEHOLD_POINTS_THRESHOLD = 3;

    /**
     * The points added for tenure over {@link #TENURE_LEVEL_DAYS} days.
     */
    public static final int TENURE_POINTS = 3;

    /**
     * The tenure, in days, that must be strictly exceeded to earn the tenure points. At or below it
     * the tenure points are not granted.
     */
    public static final long TENURE_LEVEL_DAYS = 365;

    private Memberships() {
    }

    /**
     * Computes an owner's membership points. Starts at 0; adds {@link #EMAIL_POINTS} when an email is
     * present; adds {@link #UNIQUE_NAME_POINTS} when {@code namesakeCount} is 0; adds
     * {@link #HOUSEHOLD_POINTS} for a household of {@link #HOUSEHOLD_POINTS_THRESHOLD} or more; adds
     * {@link #TENURE_POINTS} when the owner's tenure is more than {@link #TENURE_LEVEL_DAYS} days.
     *
     * @param email            the owner's email, or {@code null} when absent
     * @param namesakeCount    the owner's namesake count, or {@code null} when unknown
     * @param householdSize    the owner's household size, or {@code null} when unknown
     * @param registrationDate the owner's registration date, or {@code null} when unknown; tenure is
     *                         measured from this date to today
     * @return the membership points, 0 or more
     */
    public static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
            LocalDate registrationDate) {
        int points = 0;
        if (email != null) {
            points += EMAIL_POINTS;
        }
        if (namesakeCount != null && namesakeCount == 0) {
            points += UNIQUE_NAME_POINTS;
        }
        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
            points += HOUSEHOLD_POINTS;
        }
        if (hasQualifyingTenure(registrationDate)) {
            points += TENURE_POINTS;
        }
        return points;
    }

    /**
     * Maps membership points to a numeric membership level: 1 (0-1 points), 2 (2-3), 3 (4-5),
     * 4 (6 or more).
     *
     * @param points the owner's membership points (see {@link #membershipPoints})
     * @return the membership level, from {@value #BASE_LEVEL} to {@value #MAX_LEVEL}
     */
    public static int membershipLevel(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return BASE_LEVEL;
    }

    /**
     * Computes an owner's numeric membership level from their fields, by mapping
     * {@link #membershipPoints} through {@link #membershipLevel(int)}.
     *
     * @param email            the owner's email, or {@code null} when absent
     * @param namesakeCount    the owner's namesake count, or {@code null} when unknown
     * @param householdSize    the owner's household size, or {@code null} when unknown
     * @param registrationDate the owner's registration date, or {@code null} when unknown; tenure is
     *                         measured from this date to today
     * @return the membership level, from {@value #BASE_LEVEL} to {@value #MAX_LEVEL}
     */
    public static int membershipLevel(String email, Integer namesakeCount, Integer householdSize,
            LocalDate registrationDate) {
        return membershipLevel(membershipPoints(email, namesakeCount, householdSize, registrationDate));
    }

    /**
     * Whether the given registration date represents tenure of more than {@link #TENURE_LEVEL_DAYS}
     * days as of today. A {@code null} (or future) registration date never qualifies.
     *
     * @param registrationDate the owner's registration date, or {@code null} when unknown
     * @return {@code true} when tenure strictly exceeds {@link #TENURE_LEVEL_DAYS} days
     */
    public static boolean hasQualifyingTenure(LocalDate registrationDate) {
        if (registrationDate == null) {
            return false;
        }
        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_LEVEL_DAYS;
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "salutation",
        expression = "java(owner == null ? null : "
            + "(owner.getTitle() == null || owner.getTitle().isBlank() ? owner.getLastName() "
            + ": owner.getTitle() + \" \" + owner.getLastName()))")
    @Mapping(target = "displayName",
        expression = "java(owner == null ? null : owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(owner == null ? null : "
            + "Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "telephoneDisplay",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.TelephoneFormats.telephoneDisplay("
            + "owner.getTelephone()))")
    @Mapping(target = "checkDigit",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.CheckDigits.luhn("
            + "owner.getCustomerCode()))")
    @Mapping(target = "householdId",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.Households.householdId("
            + "owner.getLastName(), owner.getPostcode()))")
    @Mapping(target = "identityKey",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.Households.identityKey("
            + "owner.getTelephone(), owner.getEmail(), "
            + "org.springframework.samples.petclinic.util.Households.householdId("
            + "owner.getLastName(), owner.getPostcode())))")
    @Mapping(target = "membershipNumber",
        expression = "java(owner == null || owner.getCustomerCode() == null "
            + "|| owner.getRegistrationDate() == null ? null : "
            + "owner.getCustomerCode() + \"-M\" "
            + "+ String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
    @Mapping(target = "membershipPoints",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.Memberships.membershipPoints("
            + "owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), "
            + "owner.getRegistrationDate()))")
    @Mapping(target = "membershipLevel",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.Memberships.membershipLevel("
            + "owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), "
            + "owner.getRegistrationDate()))")
    @Mapping(target = "locality",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.Localities.region("
            + "owner.getPostcode(), owner.getCity()))")
    @Mapping(target = "timezone",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.Localities.timezone("
            + "owner.getPostcode(), owner.getCity()))")
    @Mapping(target = "contactPreference",
        expression = "java(owner == null ? null : "
            + "(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\"))")
    @Mapping(target = "ageBand",
        expression = "java(owner == null ? null : "
            + "org.springframework.samples.petclinic.util.AgeBands.ageBand("
            + "owner.getBirthDate(), owner.getRegistrationDate()))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

