26	public final class AgeBands {
27	
28	    /**
29	     * The age (inclusive) at which an owner is no longer a {@code MINOR}.
30	     */
31	    public static final int ADULT_AGE = 18;
32	
33	    /**
34	     * The age (inclusive) at which an owner becomes a {@code SENIOR}.
35	     */
36	    public static final int SENIOR_AGE = 65;
37	
38	    private AgeBands() {
39	    }
40	
41	    /**
42	     * Computes an owner's age band from their birth date relative to their registration date:
43	     * {@code 'MINOR'} when under {@value #ADULT_AGE}, {@code 'ADULT'} from {@value #ADULT_AGE} to
44	     * {@value #SENIOR_AGE} minus one, {@code 'SENIOR'} at {@value #SENIOR_AGE} or older. Returns
45	     * {@code null} when either date is absent (no birth date was supplied).
46	     *
47	     * @param birthDate        the owner's birth date, or {@code null} when absent
48	     * @param registrationDate the owner's registration date the age is measured against
49	     * @return the age band, or {@code null} when it cannot be derived
50	     */
51	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
52	        if (birthDate == null || registrationDate == null) {
53	            return null;
54	        }
55	        int age = Period.between(birthDate, registrationDate).getYears();
56	        if (age < ADULT_AGE) {
57	            return "MINOR";
58	        }
59	        if (age < SENIOR_AGE) {
60	            return "ADULT";
61	        }
62	        return "SENIOR";
63	    }
64	}
