    public static boolean hasQualifyingTenure(LocalDate registrationDate) {
        if (registrationDate == null) {
            return false;
        }
        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_LEVEL_DAYS;
    }
